import 'dart:async'; import 'package:flutter/material.dart'; import '../../../core/network/football_repository.dart';
class RealtimeMatchScreen extends StatefulWidget{const RealtimeMatchScreen({super.key,required this.matchId});final int matchId;@override State<RealtimeMatchScreen> createState()=>_RealtimeMatchScreenState();}
class _RealtimeMatchScreenState extends State<RealtimeMatchScreen>{final repo=FootballRepository();Timer? timer;Map<String,dynamic>? data;String? error;int after=0;@override void initState(){super.initState();load();timer=Timer.periodic(const Duration(seconds:6),(_)=>load());}@override void dispose(){timer?.cancel();super.dispose();}Future<void> load()async{try{final d=await repo.realtime(widget.matchId,after:after);final c=List<dynamic>.from(d['commentary']??[]);if(c.isNotEmpty)after=(c.last['id']??after) as int;if(!mounted)return;setState(()=>data=d);}catch(e){if(mounted)setState(()=>error=e.toString());}}@override Widget build(BuildContext context){final d=data;if(d==null)return Scaffold(appBar:AppBar(title:const Text('Live Center')),body:Center(child:error==null?const CircularProgressIndicator():Text(error!)));final m=Map<String,dynamic>.from(d['match']??{});final comments=List<dynamic>.from(d['commentary']??[]);return Scaffold(appBar:AppBar(title:const Text('Realtime Match')),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(children:[Text('${m['home_team']?['name_en']??''}  ${m['home_score']??0} - ${m['away_score']??0}  ${m['away_team']?['name_en']??''}',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:6),Text('${m['status']??''} • ${m['minute']??0}\' • ${d['state']??'idle'}')]))),const SizedBox(height:12),Text('Live commentary',style:Theme.of(context).textTheme.titleMedium),...comments.reversed.map((x)=>ListTile(leading:CircleAvatar(child:Text('${x['minute']??''}')),title:Text('${x['text']??''}'),subtitle:Text('${x['type']??'commentary'}')))])));}}
